import pandas as pd
import numpy as np
import json

# Load data and chart images
df = pd.read_csv('benchmark/data.csv')
with open('output/chart_data.json', 'r') as f:
    charts = json.load(f)

# ============================================
# COMPUTE ALL METRICS
# ============================================

ai_risk_by_year = df.groupby('year')['ai_risk_score'].mean()
salary_by_year = df.groupby('year')['salary'].median()
job_openings_by_year = df.groupby('year')['job_openings'].sum()

risk_2015 = ai_risk_by_year.iloc[0]
risk_2035 = ai_risk_by_year.iloc[-1]
risk_increase = ((risk_2035 - risk_2015) / risk_2015) * 100

salary_2015 = salary_by_year.iloc[0]
salary_2035 = salary_by_year.iloc[-1]
salary_increase = ((salary_2035 - salary_2015) / salary_2015) * 100

openings_2015 = job_openings_by_year.iloc[0]
openings_2035 = job_openings_by_year.iloc[-1]
openings_change = ((openings_2035 - openings_2015) / openings_2015) * 100

survival_2015 = (df[df['year'] == 2015]['job_survival_class'] >= 1).mean() * 100
survival_2035 = (df[df['year'] == 2035]['job_survival_class'] >= 1).mean() * 100

ai_risk_by_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=False)
high_risk_role = ai_risk_by_job.index[0]
high_risk_score = ai_risk_by_job.iloc[0]
low_risk_role = ai_risk_by_job.index[-1]
low_risk_score = ai_risk_by_job.iloc[-1]

salary_risk_corr = df['salary'].corr(df['ai_risk_score'])

skill_2015 = df[df['year'] == 2015].groupby('primary_skill')['skill_demand_score'].mean()
skill_2035 = df[df['year'] == 2035].groupby('primary_skill')['skill_demand_score'].mean()
skill_growth = ((skill_2035 - skill_2015) / skill_2015 * 100).sort_values(ascending=False)
top_growing_skill = skill_growth.index[0]
top_growth_pct = skill_growth.iloc[0]

survival_by_role_skill = df.groupby(['job_title', 'primary_skill'])['job_survival_class'].mean().sort_values(ascending=False)
best_combo = survival_by_role_skill.index[0]
best_combo_score = survival_by_role_skill.iloc[0]

salary_by_country = df.groupby('country')['salary'].median().sort_values(ascending=False)
top_paying_country = salary_by_country.index[0]
top_pay = salary_by_country.iloc[0]

risk_by_country = df.groupby('country')['ai_risk_score'].mean().sort_values(ascending=False)
highest_risk_country = risk_by_country.index[0]

salary_by_exp = df.groupby('experience_level')['salary'].median().sort_values(ascending=False)
survival_by_exp = df.groupby('experience_level')['job_survival_class'].mean().sort_values(ascending=False)

survival_by_edu = df.groupby('education_level')['job_survival_class'].mean().sort_values(ascending=False)

salary_by_risk = df.groupby('ai_risk_category')['salary'].median()

openings_by_job = df.groupby('job_title')['job_openings'].sum().sort_values(ascending=False)

at_risk_top3 = ai_risk_by_job.head(3)
resilient_top3 = ai_risk_by_job.tail(3)

salary_by_job = df.groupby('job_title')['salary'].median().sort_values(ascending=False)
survival_by_job = df.groupby('job_title')['job_survival_class'].mean().sort_values(ascending=False)
skill_demand_avg = df.groupby('primary_skill')['skill_demand_score'].mean().sort_values(ascending=False)

declining_skill = skill_growth.index[-1]
decline_pct = skill_growth.iloc[-1]

openings_peak_year = job_openings_by_year.idxmax()
openings_peak_val = job_openings_by_year.max()

risk_2024 = ai_risk_by_year.loc[2024]
risk_accel = ((risk_2035 - risk_2024) / risk_2024) * 100

high_risk_salary = df[df['ai_risk_category'] == 'High Risk']['salary'].median()
low_risk_salary = df[df['ai_risk_category'] == 'Low Risk']['salary'].median()
salary_gap = ((low_risk_salary - high_risk_salary) / high_risk_salary) * 100

senior_salary = df[df['experience_level'] == 'Senior']['salary'].median()
entry_salary = df[df['experience_level'] == 'Entry']['salary'].median()
exp_premium = ((senior_salary - entry_salary) / entry_salary) * 100

senior_survival = df[df['experience_level'] == 'Senior']['job_survival_class'].mean()
entry_survival = df[df['experience_level'] == 'Entry']['job_survival_class'].mean()

# Data tables
table_risk_by_role = df.groupby('job_title').agg({
    'ai_risk_score': 'mean',
    'salary': 'median',
    'job_openings': 'sum',
    'job_survival_class': 'mean'
}).round(3).reset_index()
table_risk_by_role.columns = ['Job Title', 'Avg AI Risk', 'Median Salary (USD)', 'Total Openings', 'Avg Survival Class']
table_risk_by_role = table_risk_by_role.sort_values('Avg AI Risk', ascending=False)

table_country = df.groupby('country').agg({
    'ai_risk_score': 'mean',
    'salary': 'median',
    'job_openings': 'sum',
    'job_survival_class': lambda x: (x >= 1).mean() * 100
}).round(2).reset_index()
table_country.columns = ['Country', 'Avg AI Risk', 'Median Salary (USD)', 'Total Openings', 'Survival Rate (%)']
table_country = table_country.sort_values('Avg AI Risk', ascending=False)

table_skill = df.groupby('primary_skill').agg({
    'skill_demand_score': 'mean',
    'ai_risk_score': 'mean',
    'job_survival_class': 'mean',
    'salary': 'median'
}).round(2).reset_index()
table_skill.columns = ['Primary Skill', 'Avg Demand Score', 'Avg AI Risk', 'Avg Survival Class', 'Median Salary (USD)']
table_skill = table_skill.sort_values('Avg Demand Score', ascending=False)

table_yearly = df.groupby('year').agg({
    'ai_risk_score': 'mean',
    'salary': 'median',
    'job_openings': 'sum',
    'skill_demand_score': 'mean',
    'job_survival_class': lambda x: (x >= 1).mean() * 100
}).round(2).reset_index()
table_yearly.columns = ['Year', 'Avg AI Risk', 'Median Salary (USD)', 'Total Openings', 'Avg Skill Demand', 'Survival Rate (%)']

# Helper to format numbers
def fmt_num(x):
    if isinstance(x, float):
        return f"{x:.2f}"
    return str(x)

def df_to_html_table(df, id_name=""):
    html = f'<table class="data-table" id="{id_name}">\n<thead>\n<tr>'
    for col in df.columns:
        html += f'<th>{col}</th>'
    html += '</tr>\n</thead>\n<tbody>\n'
    for _, row in df.iterrows():
        html += '<tr>'
        for val in row:
            if isinstance(val, float):
                html += f'<td>{val:,.2f}</td>'
            elif isinstance(val, int):
                html += f'<td>{val:,}</td>'
            else:
                html += f'<td>{val}</td>'
        html += '</tr>\n'
    html += '</tbody>\n</table>'
    return html

