    html = f'<table class="data-table" id="{id_name}">\n<thead>\n<tr>'
    for col in df.columns:
        html += f'<th>{col}</th>'
    html += '</tr>\n</thead>\n<tbody>\n'
    for _, row in df.iterrows():
        html += '<tr>'
        for val in row:
            if isinstance(val, float):
